def kth_smallest(root, k):
    stack, node = [], root
    while True:
        while node is not None:
            stack.append(node)
            node = node.left
        node = stack.pop()
        k -= 1
        if k == 0:
            return node.val
        node = node.right

def kth_smallest(root, k):
    answer, node = None, root
    while node is not None:
        if node.left is None:
            k -= 1
            if k == 0:
                answer = node.val
            node = node.right
            continue
        pred = node.left
        while pred.right is not None and pred.right is not node:
            pred = pred.right
        if pred.right is None:
            pred.right = node               # create the thread, go left
            node = node.left
        else:
            pred.right = None               # left side done: remove the thread
            k -= 1
            if k == 0:
                answer = node.val
            node = node.right
    return answer
